"""Generates src/locale/us-tier-mix.ts from docs/us-tier-mix-seeds70-79.json (us-baseline --measure-tier output, aggregated).
Usage: python -I -X utf8 scripts/us-tier-mix-build.py   (run from the repo root)"""
import json

d = json.load(open("docs/us-tier-mix-seeds70-79.json", encoding="utf-8"))
out = [
    "/**",
    " * Mean engine risk-tier death probability per principal diagnosis in a US world (Epic X M10.5c step E).",
    " * GENERATED by scripts/us-tier-mix-build.py from docs/us-tier-mix-seeds70-79.json; do not edit by hand.",
    f" * Measured on {len(d['seeds'])} seeds ({d['source']}), {d['discharges']} discharges.",
    " * Used to scale the HCUP in-hospital death rate by a patient's tier relative to the diagnosis average.",
    " */",
    f"export const US_TIER_GLOBAL = {{ n: {d['discharges']}, mean: {round(d['sumTierProbability'] / d['discharges'], 5)} }};",
    "",
    "/** [discharges, mean tier probability] per 3-character ICD-10 category. */",
    "export const US_TIER_BY_ICD: Readonly<Record<string, readonly [number, number]>> = {",
]
for k, v in d["byIcd"].items():
    out.append(f"  {k}: [{v['n']}, {round(v['sum'] / v['n'], 5)}],")
out.append("};")
out.append("")
open("src/locale/us-tier-mix.ts", "w", encoding="utf-8", newline="\n").write("\n".join(out))
print(len(d["byIcd"]), "codes")
